defmodule Solution do def num_squares(n) do cond do square?(n) -> 1; rem(strip_four(n), 8) == 7 -> 4; two_squares?(n, 1) -> 2; true -> 3 end end; defp square?(n) do root = trunc(:math.sqrt(n)); root * root == n end; defp strip_four(n) when rem(n, 4) == 0, do: strip_four(div(n, 4)); defp strip_four(n), do: n; defp two_squares?(n, value) when value * value > n, do: false; defp two_squares?(n, value), do: square?(n - value * value) or two_squares?(n, value + 1) end
